CREATE OR REPLACE FUNCTION clinical.shri_resource_table(resource_type text) RETURNS text
LANGUAGE sql IMMUTABLE AS $$ SELECT CASE resource_type WHEN 'AllergyIntolerance' THEN 'allergy_intolerance' WHEN 'Appointment' THEN 'appointment' WHEN 'Composition' THEN 'composition' WHEN 'Condition' THEN 'condition' WHEN 'Consent' THEN 'consent' WHEN 'Coverage' THEN 'coverage' WHEN 'DetectedIssue' THEN 'detected_issue' WHEN 'DiagnosticReport' THEN 'diagnostic_report' WHEN 'DocumentReference' THEN 'document_reference' WHEN 'Encounter' THEN 'encounter' WHEN 'FamilyMemberHistory' THEN 'family_member_history' WHEN 'Immunization' THEN 'immunization' WHEN 'Location' THEN 'location' WHEN 'Medication' THEN 'medication' WHEN 'MedicationDispense' THEN 'medication_dispense' WHEN 'MedicationRequest' THEN 'medication_request' WHEN 'MedicationStatement' THEN 'medication_statement' WHEN 'Observation' THEN 'observation' WHEN 'Organization' THEN 'organization' WHEN 'Patient' THEN 'patient' WHEN 'Practitioner' THEN 'practitioner' WHEN 'PractitionerRole' THEN 'practitioner_role' WHEN 'Procedure' THEN 'procedure' WHEN 'Provenance' THEN 'provenance' WHEN 'RelatedPerson' THEN 'related_person' WHEN 'Schedule' THEN 'schedule' WHEN 'ServiceRequest' THEN 'service_request' WHEN 'Specimen' THEN 'specimen' END $$;

